<?php
declare(strict_types=1);
require __DIR__.'/patient-summary.php';
use App\Services\{CareService,NursingWorklistService,Crypto};
$nursingCare=new CareService($s,$nurse);$worklist=new NursingWorklistService($nursingCare);
$queuePatient=$s->insert('patients',['company_id'=>1,'name'=>'Maria Fictícia da Fila']);
$s->insert('care_team_assignments',['company_id'=>1,'patient_id'=>$queuePatient,'team_id'=>1]);
$queuePlan=$nursingCare->create(array_replace($data,['patient_id'=>$queuePatient,'start_date'=>date('Y-m-d',time()-86400),'reassessment_date'=>date('Y-m-d'),'status'=>'active']))['id'];
$appointment=$s->insert('appointments',['company_id'=>1,'patient_id'=>$queuePatient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()+3600),'status'=>'expected']);
$worklist->sync();$patientItems=array_values(array_filter($worklist->queue()['items'],fn($i)=>(int)$i['patient_id']===$queuePatient));
verify(count($patientItems)===2,'Worklist combines return and plan review');
verify($worklist->sync()['created']===0,'Worklist synchronization is idempotent');
$returnItem=array_values(array_filter($patientItems,fn($i)=>$i['source_type']==='case'))[0];
$reviewItem=array_values(array_filter($patientItems,fn($i)=>$i['source_type']==='plan'))[0];
verify(str_contains($returnItem['priority_reason'],'não representa risco clínico'),'Administrative priority is explicit');
foreach([$admin,$manager,$navigator,$worker,$dependent] as $actor) {
    $deniedService=new NursingWorklistService(new CareService($s,$actor));
    denied(fn()=>$deniedService->queue(),403);denied(fn()=>$deniedService->detail((int)$returnItem['id']),403);denied(fn()=>$deniedService->sync(),403);
}
$foreign=new NursingWorklistService(new CareService($s,$s->one('SELECT * FROM users WHERE id=7')));
denied(fn()=>$foreign->detail((int)$returnItem['id']),404);
$s->execute('UPDATE care_team_assignments SET active=0 WHERE patient_id=?',[$queuePatient]);
denied(fn()=>$worklist->detail((int)$returnItem['id']),404);
verify(!array_filter($worklist->queue()['items'],fn($i)=>(int)$i['patient_id']===$queuePatient),'Revoked patient disappears from queue');
$s->execute('UPDATE care_team_assignments SET active=1 WHERE patient_id=?',[$queuePatient]);
denied(fn()=>$worklist->queue(['status'=>'invalid']),422);denied(fn()=>$worklist->queue(['team_id'=>'1 OR 1=1']),422);
$detail=$worklist->detail((int)$returnItem['id']);
verify($detail['summary']['patient']['id']===$queuePatient && count($detail['appointments'])===1,'Follow-up sheet tied to exact patient');
verify($detail['summary']['last_attended']===null,'Expected return never becomes attendance');
$events=count($detail['history']);
denied(fn()=>$worklist->action((int)$returnItem['id'],['version'=>(int)$detail['version'],'type'=>'attendance']),422);
verify(count($worklist->detail((int)$returnItem['id'])['history'])===$events,'Failed attendance rolls back all queue events');
$result=$worklist->action((int)$returnItem['id'],['version'=>(int)$detail['version'],'type'=>'contact','note'=>'Contato fictício realizado.','channel'=>'phone','outcome'=>'no_answer']);
verify($worklist->detail((int)$returnItem['id'])['status']==='in_progress','Contact does not confirm attendance');
$raw=$s->one('SELECT note FROM care_pending_events WHERE item_id=? AND event_type=?',[$returnItem['id'],'contact']);
verify($raw['note']!=='Contato fictício realizado.' && Crypto::decrypt($raw['note'])==='Contato fictício realizado.','Follow-up notes encrypted at rest');
denied(fn()=>$worklist->action((int)$returnItem['id'],['version'=>(int)$detail['version'],'type'=>'start']),409);
denied(fn()=>$worklist->action((int)$returnItem['id'],['version'=>$result['version'],'type'=>'assign','assigned_to'=>7]),422);
$result=$worklist->action((int)$returnItem['id'],['version'=>$result['version'],'type'=>'assign','assigned_to'=>2]);
verify(count($worklist->queue(['assigned_to'=>'2'])['items'])>=1,'Assignment filter uses authorized responsible');
$result=$worklist->action((int)$returnItem['id'],['version'=>$result['version'],'type'=>'difficulty','barrier'=>'declined']);
verify($s->one('SELECT barrier FROM continuity_cases WHERE id=?',[$returnItem['source_id']])['barrier']==='declined','Worker may decline explanation');
$result=$worklist->action((int)$returnItem['id'],['version'=>$result['version'],'type'=>'nursing_record','plan_id'=>$queuePlan,'note'=>'Acompanhamento de enfermagem fictício.']);
verify($worklist->detail((int)$returnItem['id'])['summary']['latest_evolution']['notes']==='Acompanhamento de enfermagem fictício.','Nursing action updates real clinical record');
denied(fn()=>(new NursingWorklistService(new CareService($s,$doctor)))->action((int)$returnItem['id'],['version'=>$result['version'],'type'=>'nursing_record','plan_id'=>$queuePlan,'note'=>'Registro indevido.']),403);
$result=$worklist->action((int)$returnItem['id'],['version'=>$result['version'],'type'=>'refer_doctor','professional_id'=>1,'team_id'=>1,'note'=>'Solicitação fictícia de revisão pela equipe.']);
verify(count($worklist->detail((int)$returnItem['id'])['summary']['recent_referrals'])===1,'Referral persists authorized destination');
$worklist->sync();$current=$worklist->detail((int)$returnItem['id']);
denied(fn()=>$worklist->action((int)$returnItem['id'],['version'=>(int)$current['version'],'type'=>'resolve','note'=>'']),422);
$worklist->action((int)$returnItem['id'],['version'=>(int)$current['version'],'type'=>'resolve','note'=>'Contato concluído; programação mantida.']);
$worklist->sync();verify($worklist->detail((int)$returnItem['id'])['status']==='resolved','Manual resolution survives repeated sync');
$s->insert('continuity_actions',['case_id'=>$returnItem['source_id'],'author_id'=>2,'action_type'=>'support_requested','administrative_note'=>Crypto::encrypt('Pedido fictício sem motivo obrigatório.'),'payload'=>'{}','created_at'=>date('Y-m-d H:i:s')]);
$worklist->sync();$current=$worklist->detail((int)$returnItem['id']);
verify($current['status']==='open' && (int)$current['help_requested']===1,'New explicit help reopens corresponding case');
$taskData=['patient_id'=>$queuePatient,'team_id'=>1,'assigned_to'=>2,'kind'=>'communication_failure','title'=>'Conferir contato fictício','due_date'=>date('Y-m-d'),'note'=>'Confirmar canal com a pessoa.'];
$taskA=$worklist->create($taskData)['id'];$taskB=$worklist->create($taskData)['id'];
verify($taskA!==$taskB,'Separate manual tasks have independent identities');
denied(fn()=>$worklist->create(array_replace($taskData,['patient_id'=>2])),404);
denied(fn()=>$worklist->create(array_replace($taskData,['assigned_to'=>7])),422);
$before=(int)$s->one('SELECT COUNT(*) n FROM clinical_evolutions')['n'];
try { $s->transaction(function()use($nursingCare,$queuePlan){$nursingCare->evolution($queuePlan,['kind'=>'nursing','notes'=>'Deve ser revertido.']);throw new RuntimeException('rollback');}); } catch(RuntimeException $e) { if($e->getMessage()!=='rollback') throw $e; }
verify((int)$s->one('SELECT COUNT(*) n FROM clinical_evolutions')['n']===$before,'Nested domain transaction rolls back with outer action');
$worklist->action((int)$returnItem['id'],['version'=>(int)$current['version'],'type'=>'reschedule','date'=>date('Y-m-d',time()+12*86400),'time'=>'13:17','note'=>'Novo horário pactuado.']);
verify($worklist->detail((int)$returnItem['id'])['status']==='resolved','Rescheduling finalizes old return item');
verify($s->one('SELECT status FROM appointments WHERE id=?',[$appointment])['status']==='rescheduled','Rescheduling updates original appointment');
$s->execute('UPDATE care_plans SET reassessment_date=? WHERE id=?',[date('Y-m-d',time()+30*86400),$queuePlan]);
$worklist->sync();verify($worklist->detail((int)$reviewItem['id'])['status']==='resolved','Future review settles obsolete pending item');
verify($s->one('SELECT id FROM audit_logs WHERE event=? AND resource_id=?',['pending_resolve',$returnItem['id']])!==null,'Resolution audited');
$pastAppointment=$s->insert('appointments',['company_id'=>1,'patient_id'=>$queuePatient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()-3600),'status'=>'confirmed']);
$worklist->sync();
$pastCase=(int)$s->one('SELECT id FROM continuity_cases WHERE appointment_id=?',[$pastAppointment])['id'];
verify($pastCase>0,'Past confirmed appointment without a legacy case enters the queue');
$attendanceItem=array_values(array_filter($worklist->queue()['items'],fn($i)=>$i['source_type']==='case' && (int)$i['source_id']===$pastCase))[0];
$worklist->action((int)$attendanceItem['id'],['version'=>(int)$attendanceItem['version'],'type'=>'attendance','note'=>'Comparecimento fictício verificado pela equipe.']);
verify($s->one('SELECT status FROM appointments WHERE id=?',[$pastAppointment])['status']==='attended','Verified past attendance persists in the appointment');
verify($worklist->detail((int)$attendanceItem['id'])['summary']['last_attended']['id']===$pastAppointment,'Follow-up sheet reflects verified attendance');
verify(!array_filter($worklist->queue(['deadline'=>'today'])['items'],fn($i)=>substr($i['due_at'],0,10)!==date('Y-m-d')),'Today filter honors actual deadline');
echo "OK: {$count} combined worklist/domain checks\n";
